define({"topics":[{"title":"Checking and adjusting the patient intercom functionality","shortdesc":"<p class=\"shortdesc\">GOC Audio Assembly (GOCAA) controls are adjusted at factory for best sound quality. This document describes how to check and confirm volume and quality of sound heard from speaker in the magnet bore and from speaker at the Scan Control and Intercom Module (SCIM). Directions for sound adjustments are also provided if needed. <\/p>","href":"t_CheckingThePatientIntercomFunctionality_2.html","attributes":{"data-id":"id_2011596"},"menu":{"hasChildren":true},"tocID":"id_2011596-d46e24062","next":"id_2011596-d46e24062"},{"title":"Examining the Global Operator Cabinet (GOC) battery replacement","shortdesc":"<p class=\"shortdesc\">Look at the battery replacement label on the GOC to see if the battery should be replaced.<\/p>","href":"t_ExaminingTheGOCBatteryReplacement.html","attributes":{"data-id":"id_2004573"},"menu":{"hasChildren":false},"tocID":"id_2004573-d46e24479","topics":[]}]});